func isGuest(id string) bool { return len(id) > 2 && id[:2] == "g-" }

func actionVerb(a string) string {
	switch a {
	case demo.ActHide:
		return "hid"
	case demo.ActRestore:
		return "restored"
	case demo.ActDelete:
		return "deleted"
	case demo.ActBlock:
		return "blocked"
	case demo.ActUnblock:
		return "unblocked"
	}
	return a
}

